//! Cross-checks the Rust obfuscation layer against vectors generated by the original Python
//! implementation (`tests/vectors.json`, produced from Flowseal/tg-ws-proxy).

use cipher::StreamCipher;
use heli_tgproxy::crypto::{
    MsgSplitter, build_crypto_ctx, generate_relay_init_from, try_handshake,
};
use serde_json::Value;

fn hex(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().expect("string")).expect("hex")
}

fn arr<const N: usize>(v: &Value) -> [u8; N] {
    hex(v).try_into().expect("length")
}

fn load() -> Value {
    serde_json::from_str(include_str!("vectors.json")).expect("vectors.json")
}

#[test]
fn handshake_relay_init_and_ciphers_match_python() {
    let doc = load();
    for (n, vec) in doc["vectors"].as_array().unwrap().iter().enumerate() {
        let secret: [u8; 16] = arr(&vec["secret"]);
        let client_init: [u8; 64] = arr(&vec["client_init"]);

        // 1. handshake decoding
        let hs = try_handshake(&client_init, &secret).unwrap_or_else(|| panic!("vector {n}: handshake rejected"));
        let exp = &vec["expected"];
        assert_eq!(u64::from(hs.dc), exp["dc"].as_u64().unwrap(), "vector {n} dc");
        assert_eq!(hs.is_media, exp["is_media"].as_bool().unwrap(), "vector {n} media");
        assert_eq!(hs.prekey_iv.to_vec(), hex(&exp["prekey_iv"]), "vector {n} prekey");
        assert_eq!(hs.proto_tag.to_vec(), hex(&vec["proto_tag"]), "vector {n} tag");

        // 2. relay init with the same "urandom" stream
        let q: Vec<Vec<u8>> = vec["urandom_queue"].as_array().unwrap().iter().map(hex).collect();
        let mut inits = q[..3].iter();
        let relay_init = generate_relay_init_from(
            hs.proto_tag,
            vec["dc_idx"].as_i64().unwrap() as i16,
            || inits.next().expect("init candidate").clone().try_into().unwrap(),
            || q[3].clone().try_into().unwrap(),
        );
        assert_eq!(relay_init.to_vec(), hex(&vec["relay_init"]), "vector {n} relay init");

        // 3. the four AES-CTR streams
        let mut ctx = build_crypto_ctx(&hs.prekey_iv, &secret, &relay_init);
        let samples: Vec<Vec<u8>> = vec["samples"].as_array().unwrap().iter().map(hex).collect();
        for (i, s) in samples.iter().enumerate() {
            for (name, cipher) in [
                ("clt_dec", &mut ctx.clt_dec),
                ("tg_enc", &mut ctx.tg_enc),
                ("tg_dec", &mut ctx.tg_dec),
                ("clt_enc", &mut ctx.clt_enc),
            ] {
                let mut buf = s.clone();
                cipher.apply_keystream(&mut buf);
                assert_eq!(buf, hex(&vec["ctx"][name][i]), "vector {n} {name} sample {i}");
            }
        }

        // 4. message splitter
        let sp = &vec["splitter"];
        let mut splitter = MsgSplitter::new(&relay_init, sp["proto_int"].as_u64().unwrap() as u32);
        let stream = hex(&sp["cipher_stream"]);
        let mut lens = Vec::new();
        let mut pos = 0;
        for cut in sp["cuts"].as_array().unwrap() {
            let cut = (cut.as_u64().unwrap() as usize).min(stream.len());
            lens.extend(splitter.split(&stream[pos..cut]).iter().map(Vec::len));
            pos = cut;
        }
        let expected: Vec<usize> =
            sp["part_lens"].as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as usize).collect();
        assert_eq!(lens, expected, "vector {n} splitter part lengths");
        let plain: Vec<usize> =
            sp["plain_packet_lens"].as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as usize).collect();
        assert_eq!(lens, plain, "vector {n} splitter == original packet sizes");
    }
}

#[test]
fn fake_tls_client_hello_verification_matches_python() {
    let doc = load();
    let f = &doc["fake_tls"];
    let secret: [u8; 16] = arr(&f["secret"]);
    let hello = hex(&f["client_hello"]);
    let ts = f["timestamp"].as_i64().unwrap();
    let ok = heli_tgproxy::fake_tls::verify_client_hello_at(&hello, &secret, ts).expect("python-built hello verifies");
    assert_eq!(i64::from(ok.timestamp), ts);
    assert_eq!(ok.client_random.to_vec(), hex(&f["client_random"]));
    assert_eq!(ok.session_id.to_vec(), hex(&f["session_id"]));
    assert!(heli_tgproxy::fake_tls::verify_client_hello_at(&hello, &[0u8; 16], ts).is_none());
}
